      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=10.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=10.00 due-total=2.00 overdue-total=0.00`,
      `PERIOD_UNLOCKED sheet=${sheet} by=vic period=P1`,
