28	
29	/** The periods of a sheet. */
30	@Service
31	public class PeriodService {
32	
33	    private final PeriodRepository periods;
34	    private final SheetService sheets;
35	    private final ClaimRepository claims;
36	    private final PersonRepository people;
37	    private final ClaimService claimService;
38	    private final SettingsService settings;
39	    private final Audit audit;
40	
41	    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
42	            PersonRepository people, ClaimService claimService, SettingsService settings, Audit audit) {
43	        this.settings = settings;
44	        this.periods = periods;
45	        this.sheets = sheets;
46	        this.claims = claims;
47	        this.people = people;
48	        this.claimService = claimService;
49	        this.audit = audit;
50	    }
51	
52	    /** The sheet's periods, by from-date. */
53	    @Transactional(readOnly = true)
54	    public List<Period> list(String sheetId) {
55	        return periods.findBySheetIdOrderByFromAsc(sheetId);
56	    }
57	
58	    /**
59	     * Adds a period; refused when its to-date is before its from-date, its name is in use on the sheet or its dates
60	     * overlap another period's. A cap, when given, is the most OPEN or PENDING claims a person may have in it.
61	     */
62	    @Transactional
63	    public Period add(String by, String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
64	        // the sheet stays locked until the transaction ends, so two periods added at once are checked in turn
65	        sheets.lock(sheetId);
66	        String trimmed = name.strip();
67	        if (to.isBefore(from)) {
68	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
69	        }
70	        if (periods.existsBySheetIdAndName(sheetId, trimmed)) {
71	            throw nameInUse();
72	        }
73	        if (periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, to, from)) {
74	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
75	        }
76	        Period added;
77	        try {
78	            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to, cap));
79	        } catch (DataIntegrityViolationException e) {
80	            throw nameInUse();
81	        }
82	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
83	                + " from=" + added.getFrom() + " to=" + added.getTo()
84	                + (added.getCap() != null ? " cap=" + added.getCap() : ""));
85	        return added;
86	    }
87	
88	    /**
89	     * Adds one period per calendar month from the from-date's month to the to-date's month, each from the first to the
90	     * last day of its month and named yyyy-mm, by month. A month whose name is in use on the sheet or whose days
91	     * overlap a period is left out; the others are still made. Refused when the to-date is before the from-date.
92	     */
93	    @Transactional
94	    public List<Period> generate(String by, String sheetId, LocalDate from, LocalDate to) {
95	        // the sheet stays locked until the transaction ends, so periods added at once are checked in turn
96	        sheets.lock(sheetId);
97	        if (to.isBefore(from)) {
98	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
99	        }
100	        List<Period> made = new ArrayList<>();
101	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
102	            String name = month.toString();
103	            LocalDate first = month.atDay(1);
104	            LocalDate last = month.atEndOfMonth();
105	            if (periods.existsBySheetIdAndName(sheetId, name)
106	                    || periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, last, first)) {
107	                continue;
108	            }
109	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
110	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
111	                    + " from=" + added.getFrom() + " to=" + added.getTo());
112	            made.add(added);
113	        }
114	        return made;
115	    }
116	
117	    /**
118	     * Adds the twelve monthly periods of the fiscal year FY<year>, the one starting on the first of the sheet's fiscal
119	     * start month in that year, exactly as {@link #generate} does for its first through its last day.
120	     */
121	    @Transactional
122	    public List<Period> generateFiscalYear(String by, String sheetId, int year) {
123	        LocalDate first = YearMonth.of(year, sheets.lock(sheetId).getFiscalStartMonth()).atDay(1);
124	        return generate(by, sheetId, first, first.plusYears(1).minusDays(1));
125	    }
126	
127	    /**
128	     * Closes the period, fixing each person's due-total for it now (the figures of their claims due by a date in it that
129	     * counted at the end of its last day, skipping n/a) and its own, the sum of those.
130	     * Refused unless the user's role may close, and when it is already closed.
131	     */
132	    @Transactional
133	    public Period close(String by, String sheetId, Long id) {
134	        // the sheet stays locked until the transaction ends, so no claim in the period changes while it closes
135	        LocalDate today = sheets.lock(sheetId).getToday();
136	        Period period = periods.findByIdAndSheetId(id, sheetId)
137	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
138	        settings.refuseUnlessMay(sheetId, by, "close");
139	        if (period.isClosed()) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
141	        }
142	        return close(by, sheetId, period, today, "");
143	    }
144	
145	    /**
146	     * Soft-closes the period, fixing its figures as a close does while claims due by a date in it can still change. Refused
147	     * unless the user's role may close, and when it is already closed or soft-closed.
148	     */
149	    @Transactional
150	    public Period softClose(String by, String sheetId, Long id) {
151	        LocalDate today = sheets.lock(sheetId).getToday();
152	        Period period = periods.findByIdAndSheetId(id, sheetId)
153	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
154	        settings.refuseUnlessMay(sheetId, by, "close");
155	        if (period.isClosed() || period.isSoftClosed()) {
156	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
157	        }
158	        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period, today);
159	        BigDecimal total = sum(personTotals);
160	        period.softClose(total, personTotals, personCarried(sheetId, period, today));
161	        Period saved = periods.saveAndFlush(period);
162	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + by + " period=" + saved.getName()
163	                + " total=" + total.toPlainString());
164	        return saved;
165	    }
166	
167	    /**
168	     * Once the sheet's today is changed while it has grace days, closes every open period (not soft-closed) whose to-date plus them is
169	     * before the new today, by to-date, each as a close by hand would.
170	     */
171	    @EventListener
172	    @Transactional
173	    public void autoClose(TodayChanged change) {
174	        Sheet sheet = change.sheet();
175	        Integer graceDays = sheet.getGraceDays();
176	        if (graceDays == null) {
177	            return;
178	        }
179	        LocalDate today = sheet.getToday();
180	        for (Period period : periods.findBySheetIdAndClosedFalseAndToBeforeOrderByToAsc(sheet.getId(),
181	                today.minusDays(graceDays))) {
182	            // a soft-closed period keeps the figures it fixed
183	            if (period.isSoftClosed()) {
184	                continue;
185	            }
186	            close(change.by(), sheet.getId(), period, today, " auto=yes");
187	        }
188	    }
189	
190	    private Period close(String by, String sheetId, Period period, LocalDate today, String auditSuffix) {
191	        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period, today);
192	        BigDecimal total = sum(personTotals);
193	        period.close(total, personTotals, personCarried(sheetId, period, today));
194	        Period saved = periods.saveAndFlush(period);
195	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + by + " period=" + saved.getName()
196	                + " total=" + total.toPlainString() + auditSuffix);
197	        return saved;
198	    }
199	
200	    private static BigDecimal sum(Map<Long, BigDecimal> personTotals) {
201	        return personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
202	    }
203	
204	    /**
205	     * Each person's due-total for the period now: the figures of their claims due by a date in it that counted at the end of
206	     * its last day, skipping n/a; 0.00 for a person with none.
207	     */
208	    private Map<Long, BigDecimal> personTotals(String sheetId, Period period, LocalDate today) {
209	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
210	                .collect(Collectors.toMap(Person::getId, Function.identity()));
211	        // every person on the sheet now gets a figure, 0.00 when none of their counted claims is due by a date in it
212	        Map<Long, BigDecimal> personTotals = new HashMap<>();
213	        for (Long personId : byId.keySet()) {
214	            personTotals.put(personId, BigDecimal.ZERO.setScale(2));
215	        }
216	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
217	            Person person = byId.get(c.getPersonId());
218	            if (person == null || !person.countsAtEndOf(c, period.getTo(), today) || !period.contains(c.getDueBy())) {
219	                continue;
220	            }
221	            BigDecimal figure = claimService.due(sheetId, person, c);
222	            if (figure != null) {
223	                personTotals.merge(person.getId(), figure, BigDecimal::add);
224	            }
225	        }
226	        return personTotals;
227	    }
228	
229	    /**
230	     * Each person's carried figure for the period now: the figures of their claims belonging to a period of the sheet
231	     * that ends before this one starts and still open or pending at the end of its last day, skipping n/a, plus their
232	     * opening balance for it; 0.00 for a person with none.
233	     */
234	    private Map<Long, BigDecimal> personCarried(String sheetId, Period period, LocalDate today) {
235	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
236	                .collect(Collectors.toMap(Person::getId, Function.identity()));
237	        List<Period> earlier = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
238	                .filter(p -> p.getTo().isBefore(period.getFrom())).toList();
239	        Map<Long, BigDecimal> carried = new HashMap<>();
240	        for (Long personId : byId.keySet()) {
241	            carried.put(personId, period.getPersonOpenings().getOrDefault(personId, BigDecimal.ZERO).setScale(2));
242	        }
243	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
244	            Person person = byId.get(c.getPersonId());
245	            if (person == null || c.getDueBy() == null || earlier.stream().noneMatch(p -> p.contains(c.getDueBy()))
246	                    || !person.countsAtEndOf(c, period.getTo(), today)
247	                    || !c.statusAtEndOf(period.getTo()).isOpen()) {
248	                continue;
249	            }
250	            BigDecimal figure = claimService.due(sheetId, person, c);
251	            if (figure != null) {
252	                carried.merge(person.getId(), figure, BigDecimal::add);
253	            }
254	        }
255	        return carried;
256	    }
257	
258	    /** A pasted line of opening balances read: the person, the period and the amount. */
259	    private record OpeningLine(Person person, Period period, BigDecimal amount) {
260	    }
261	
262	    /**
263	     * Reads every pasted line of name,period,amount first (a person on the sheet by name or alias, a period on the sheet
264	     * by name, an amount of two decimals at most, 0.00 or more), then adds each line's amount to the person's opening
265	     * balance for the period, in order. One change: any line refused refuses them all, and nothing is stored or audited.
266	     * Answers how many lines went through.
267	     */
268	    @Transactional
269	    public int importOpenings(String by, String sheetId, String text) {
270	        sheets.lock(sheetId);
271	        Map<String, Period> byName = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
272	                .collect(Collectors.toMap(Period::getName, Function.identity()));
273	        List<OpeningLine> lines = new ArrayList<>();
274	        int n = 0;
275	        for (String raw : text.split("\\r?\\n")) {
276	            n++;
277	            if (raw.isBlank()) {
278	                continue;
279	            }
280	            String[] f = raw.split(",", -1);
281	            if (f.length != 3) {
282	                throw refused("Line " + n + " is not name,period,amount.");
283	            }
284	            String name = f[0].strip();
285	            Person person = name.isEmpty() ? null : people.findBySheetIdAndNameOrAlias(sheetId, name).orElse(null);
286	            if (person == null) {
287	                throw refused("Line " + n + " names no one on the sheet.");
288	            }
289	            Period period = byName.get(f[1].strip());
290	            if (period == null) {
291	                throw refused("Line " + n + " names no period on the sheet.");
292	            }
293	            BigDecimal amount;
294	            try {
295	                amount = new BigDecimal(f[2].strip());
296	            } catch (NumberFormatException e) {
297	                throw refused("Line " + n + " has no amount.");
298	            }
299	            if (amount.scale() > 2 || amount.precision() - amount.scale() > 12) {
300	                throw refused("Line " + n + " has an amount with more than two decimals.");
301	            }
302	            if (amount.signum() < 0) {
303	                throw refused("Line " + n + " has an amount below 0.00.");
304	            }
305	            lines.add(new OpeningLine(person, period, amount.setScale(2)));
306	        }
307	        if (lines.isEmpty()) {
308	            throw refused("Paste at least one line of name,period,amount.");
309	        }
310	        for (OpeningLine l : lines) {
311	            l.period().addOpening(l.person().getId(), l.amount());
312	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + by + " name=" + l.person().getName()
313	                    + " period=" + l.period().getName() + " amount=" + l.amount().toPlainString());
314	        }
315	        periods.saveAllAndFlush(lines.stream().map(OpeningLine::period).distinct().toList());
316	        return lines.size();
317	    }
318	
319	    private static ResponseStatusException refused(String reason) {
320	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
321	    }
322	
323	    /**
324	     * Reopens a closed or soft-closed period, making its due-total live again. Refused unless the user's role may reopen (a steward by
325	     * the standing rule), or when the period is not closed.
326	     */
327	    @Transactional
328	    public Period reopen(String by, String sheetId, Long id) {
329	        sheets.lock(sheetId);
330	        Period period = periods.findByIdAndSheetId(id, sheetId)
331	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
332	        settings.refuseUnlessMay(sheetId, by, "reopen");
333	        if (!period.isClosed() && !period.isSoftClosed()) {
334	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
335	        }
336	        period.reopen();
337	        Period saved = periods.saveAndFlush(period);
338	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + by + " period=" + saved.getName());
339	        return saved;
340	    }
341	
342	    private static ResponseStatusException nameInUse() {
343	        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
344	    }
345	}
